window.editSection=i=>{const s=i>=0?S.cache.sections[i]:{id:nowId('SEC'),nombre:'Nueva sección',descripcion:'',modo:'manual',tipo_contenido:'videos',layout:'landscape',query:'',max_items:18,activa:true,items:[]};modal(i>=0?'Editar sección':'Nueva sección',`<div class="form-grid">${f('sId','ID interno',s.id||'')}${f('sName','Título',s.nombre||'')}${f('sDesc','Descripción',s.descripcion||'','','span-2')}${sel('sMode','Modo',s.modo||'manual',[['manual','Manual'],['auto','Automática'],['hybrid','Híbrida']])}${sel('sType','Tipo',s.tipo_contenido||'videos',[['videos','Videos'],['perfiles','Artistas / perfiles'],['eventos','Eventos'],['radios','Radios'],['contenido','Contenido universal'],['mixto','Mixto']])}${sel('sLayout','Diseño',s.layout||'landscape',[['landscape','Horizontal 16:9'],['poster','Poster'],['square','Cuadrada'],['circle','Circular'],['radio','Radio'],['event','Evento']])}${f('sMax','Máximo de items',s.max_items||18,'number')}${f('sQuery','Búsqueda automática',s.query||'','','span-2')}${sel('sCollection','Colección base',s.collection_id||'',[['','Ninguna'],...arr(S.cache.collections).map(c=>[c.id,c.titulo||c.id])])}${f('sIcon','Icono / clase',s.icono||'')}${sel('sActive','Visible',s.activa===false?'false':'true',[['true','Sí'],['false','No']])}</div><div style="margin-top:14px"><div class="mini-label">Items manuales (JSON)</div><textarea id="sItems" class="textarea" style="min-height:180px">${esc(JSON.stringify(s.items||[],null,2))}</textarea><small style="color:var(--muted)">En modo híbrido, los items manuales quedan primero y el sistema completa el resto automáticamente.</small></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveSection(${i})">Guardar</button>`)};
window.saveSection=i=>{let items=[];try{items=JSON.parse($('sItems').value||'[]');if(!Array.isArray(items))throw new Error()}catch{return toast('Items debe ser un arreglo JSON válido','bad')}const s={...(i>=0?S.cache.sections[i]:{}),id:$('sId').value.trim()||nowId('SEC'),nombre:$('sName').value.trim(),descripcion:$('sDesc').value.trim(),modo:$('sMode').value,tipo_contenido:$('sType').value,layout:$('sLayout').value,max_items:Math.max(1,Number($('sMax').value||18)),query:$('sQuery').value.trim(),collection_id:$('sCollection').value,icono:$('sIcon').value.trim(),activa:$('sActive').value==='true',items};if(!s.nombre)return toast('Título obligatorio','bad');if(i>=0)S.cache.sections[i]=s;else S.cache.sections.push(s);closeModal();renderHome()};
